#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n\n\"\"\"\nDatabase migrations for version management\nProvides schema versioning and upgrade paths\n\"\"\"\n\nimport sqlite3\nimport logging\nfrom datetime import datetime\nfrom typing import List, Callable\n\nlogger = logging.getLogger(__name__)\n\n\nclass Migration:\n    \"\"\"Base migration class\"\"\"\n    \n    version: int\n    description: str\n    \n    def up(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Apply migration\"\"\"\n        raise NotImplementedError\n    \n    def down(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Rollback migration\"\"\"\n        raise NotImplementedError\n\n\nclass Migration001_InitialSchema(Migration):\n    \"\"\"Initial schema migration\"\"\"\n    \n    version = 1\n    description = \"Create initial database schema\"\n    \n    def up(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Create initial tables\"\"\"\n        cursor = conn.cursor()\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS users (\n                user_id INTEGER PRIMARY KEY,\n                fan_number TEXT UNIQUE NOT NULL,\n                authenticated BOOLEAN DEFAULT 0,\n                session_token TEXT,\n                fayda_user_data TEXT,\n                language TEXT DEFAULT 'en',\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n            )\n        ''')\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS otp_requests (\n                request_id TEXT PRIMARY KEY,\n                user_id INTEGER NOT NULL,\n                fan_number TEXT NOT NULL,\n                otp_code TEXT NOT NULL,\n                attempts INTEGER DEFAULT 0,\n                max_attempts INTEGER DEFAULT 3,\n                verified BOOLEAN DEFAULT 0,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                expires_at TIMESTAMP NOT NULL,\n                FOREIGN KEY (user_id) REFERENCES users(user_id)\n            )\n        ''')\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS download_requests (\n                request_id TEXT PRIMARY KEY,\n                user_id INTEGER NOT NULL,\n                fan_number TEXT NOT NULL,\n                document_type TEXT NOT NULL,\n                status TEXT DEFAULT 'pending',\n                error_message TEXT,\n                file_path TEXT,\n                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                FOREIGN KEY (user_id) REFERENCES users(user_id)\n            )\n        ''')\n        \n        conn.commit()\n        logger.info(\"Migration 001: Initial schema created\")\n    \n    def down(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Rollback initial schema\"\"\"\n        cursor = conn.cursor()\n        cursor.execute('DROP TABLE IF EXISTS download_requests')\n        cursor.execute('DROP TABLE IF EXISTS otp_requests')\n        cursor.execute('DROP TABLE IF EXISTS users')\n        conn.commit()\n        logger.info(\"Migration 001: Rolled back\")\n\n\nclass Migration002_AddIndexes(Migration):\n    \"\"\"Add database indexes for performance\"\"\"\n    \n    version = 2\n    description = \"Add database indexes for optimization\"\n    \n    def up(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Add indexes\"\"\"\n        cursor = conn.cursor()\n        \n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_user_fan ON users(fan_number)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_otp_user ON otp_requests(user_id)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_otp_verified ON otp_requests(verified)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_otp_expires ON otp_requests(expires_at)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_download_user ON download_requests(user_id)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_download_status ON download_requests(status)')\n        \n        conn.commit()\n        logger.info(\"Migration 002: Indexes added\")\n    \n    def down(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Remove indexes\"\"\"\n        cursor = conn.cursor()\n        \n        cursor.execute('DROP INDEX IF EXISTS idx_user_fan')\n        cursor.execute('DROP INDEX IF EXISTS idx_otp_user')\n        cursor.execute('DROP INDEX IF EXISTS idx_otp_verified')\n        cursor.execute('DROP INDEX IF EXISTS idx_otp_expires')\n        cursor.execute('DROP INDEX IF EXISTS idx_download_user')\n        cursor.execute('DROP INDEX IF EXISTS idx_download_status')\n        \n        conn.commit()\n        logger.info(\"Migration 002: Rolled back\")\n\n\nclass Migration003_AddAuditLog(Migration):\n    \"\"\"Add audit logging table\"\"\"\n    \n    version = 3\n    description = \"Add audit log table for tracking all operations\"\n    \n    def up(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Create audit log table\"\"\"\n        cursor = conn.cursor()\n        \n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS audit_logs (\n                log_id INTEGER PRIMARY KEY AUTOINCREMENT,\n                user_id INTEGER,\n                action TEXT NOT NULL,\n                details TEXT,\n                timestamp TIMESTAMP DEFAULT CURRENT_TIMESTAMP,\n                FOREIGN KEY (user_id) REFERENCES users(user_id)\n            )\n        ''')\n        \n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_audit_user ON audit_logs(user_id)')\n        cursor.execute('CREATE INDEX IF NOT EXISTS idx_audit_timestamp ON audit_logs(timestamp)')\n        \n        conn.commit()\n        logger.info(\"Migration 003: Audit log table added\")\n    \n    def down(self, conn: sqlite3.Connection) -> None:\n        \"\"\"Remove audit log table\"\"\"\n        cursor = conn.cursor()\n        cursor.execute('DROP TABLE IF EXISTS audit_logs')\n        conn.commit()\n        logger.info(\"Migration 003: Rolled back\")\n\n\nclass MigrationManager:\n    \"\"\"Manages database migrations\"\"\"\n    \n    MIGRATIONS: List[Migration] = [\n        Migration001_InitialSchema(),\n        Migration002_AddIndexes(),\n        Migration003_AddAuditLog(),\n    ]\n    \n    def __init__(self, db_path: str):\n        \"\"\"Initialize migration manager\"\"\"\n        self.db_path = db_path\n        self.conn = sqlite3.connect(db_path)\n        self._init_migrations_table()\n    \n    def _init_migrations_table(self) -> None:\n        \"\"\"Create migrations tracking table\"\"\"\n        cursor = self.conn.cursor()\n        cursor.execute('''\n            CREATE TABLE IF NOT EXISTS schema_migrations (\n                version INTEGER PRIMARY KEY,\n                description TEXT,\n                executed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP\n            )\n        ''')\n        self.conn.commit()\n    \n    def get_current_version(self) -> int:\n        \"\"\"Get current schema version\"\"\"\n        cursor = self.conn.cursor()\n        cursor.execute('SELECT MAX(version) FROM schema_migrations')\n        result = cursor.fetchone()\n        return result[0] if result[0] else 0\n    \n    def get_executed_migrations(self) -> List[int]:\n        \"\"\"Get list of executed migration versions\"\"\"\n        cursor = self.conn.cursor()\n        cursor.execute('SELECT version FROM schema_migrations ORDER BY version')\n        return [row[0] for row in cursor.fetchall()]\n    \n    def migrate_up(self, target_version: int = None) -> bool:\n        \"\"\"Apply migrations up to target version\"\"\"\n        try:\n            current = self.get_current_version()\n            executed = self.get_executed_migrations()\n            \n            if target_version is None:\n                target_version = len(self.MIGRATIONS)\n            \n            for migration in self.MIGRATIONS:\n                if migration.version <= current or migration.version in executed:\n                    continue\n                \n                if migration.version > target_version:\n                    break\n                \n                logger.info(f\"Applying migration {migration.version}: {migration.description}\")\n                migration.up(self.conn)\n                \n                cursor = self.conn.cursor()\n                cursor.execute('''\n                    INSERT INTO schema_migrations (version, description)\n                    VALUES (?, ?)\n                ''', (migration.version, migration.description))\n                self.conn.commit()\n                \n                logger.info(f\"Migration {migration.version} applied successfully\")\n            \n            return True\n        except Exception as e:\n            logger.error(f\"Migration error: {str(e)}\")\n            self.conn.rollback()\n            return False\n    \n    def migrate_down(self, target_version: int) -> bool:\n        \"\"\"Rollback migrations down to target version\"\"\"\n        try:\n            executed = self.get_executed_migrations()\n            \n            # Rollback in reverse order\n            for migration in reversed(self.MIGRATIONS):\n                if migration.version not in executed or migration.version <= target_version:\n                    continue\n                \n                logger.info(f\"Rolling back migration {migration.version}\")\n                migration.down(self.conn)\n                \n                cursor = self.conn.cursor()\n                cursor.execute('DELETE FROM schema_migrations WHERE version = ?', (migration.version,))\n                self.conn.commit()\n                \n                logger.info(f\"Migration {migration.version} rolled back successfully\")\n            \n            return True\n        except Exception as e:\n            logger.error(f\"Rollback error: {str(e)}\")\n            self.conn.rollback()\n            return False\n    \n    def get_status(self) -> dict:\n        \"\"\"Get migration status\"\"\"\n        current = self.get_current_version()\n        latest = len(self.MIGRATIONS)\n        executed = self.get_executed_migrations()\n        \n        return {\n            'current_version': current,\n            'latest_version': latest,\n            'is_up_to_date': current == latest,\n            'executed_migrations': executed,\n            'pending_migrations': [m.version for m in self.MIGRATIONS if m.version > current]\n        }\n    \n    def close(self) -> None:\n        \"\"\"Close database connection\"\"\"\n        self.conn.close()\n\n\n# Function to initialize migrations\ndef initialize_migrations(db_path: str) -> bool:\n    \"\"\"Initialize and apply all pending migrations\"\"\"\n    try:\n        manager = MigrationManager(db_path)\n        status = manager.get_status()\n        \n        logger.info(f\"Migration status: {status}\")\n        \n        if not status['is_up_to_date']:\n            logger.info(f\"Applying {len(status['pending_migrations'])} pending migrations\")\n            success = manager.migrate_up()\n            manager.close()\n            return success\n        else:\n            logger.info(\"Database schema is up to date\")\n            manager.close()\n            return True\n    except Exception as e:\n        logger.error(f\"Failed to initialize migrations: {str(e)}\")\n        return False\n"